import json
from collections import defaultdict

# Analyze all available log files
import glob
log_files = sorted(glob.glob('/root/.nanobot/request_logs/*.jsonl'))

repeat_cases = []

for log_file in log_files:
    try:
        with open(log_file) as f:
            lines = f.readlines()

        # Build timeline per session
        sessions = defaultdict(list)
        for line in lines:
            try:
                d = json.loads(line)
                session = d.get('session', 'unknown')
                agent = d.get('agent', '?')
                ts = d.get('ts', '?')

                # Track tool calls
                for tc in d.get('reply_tool_calls', []):
                    name = tc.get('name', '?')
                    args = tc.get('args', '')
                    if isinstance(args, dict):
                        args_str = json.dumps(args, sort_keys=True, ensure_ascii=False)[:100]
                    elif isinstance(args, str):
                        args_str = args[:100]
                    else:
                        args_str = str(args)[:100]
                    sessions[session].append({
                        'ts': ts,
                        'agent': agent,
                        'tool': name,
                        'args': args_str,
                    })

                # Track compression events
                for m in d.get('messages', []):
                    c = m.get('content', '')
                    if '早期对话摘要' in c and '压缩了' in c:
                        sessions[session].append({
                            'ts': ts,
                            'agent': 'SYSTEM',
                            'tool': 'COMPRESSION',
                            'args': c[:80],
                        })
            except:
                pass

        # Find repeated tool calls around compression events
        for session, events in sessions.items():
            compression_times = [e['ts'] for e in events if e['tool'] == 'COMPRESSION']

            for comp_ts in compression_times:
                # Get tool calls before and after compression
                before = [e for e in events if e['ts'] < comp_ts and e['tool'] not in ('COMPRESSION', 'chatroom_send', 'wait', 'end_discussion')]
                after = [e for e in events if e['ts'] >= comp_ts and e['tool'] not in ('COMPRESSION', 'chatroom_send', 'wait', 'end_discussion')]

                # Check for same tool+args appearing both before and after
                before_set = {(e['tool'], e['args']) for e in before}
                for e in after:
                    key = (e['tool'], e['args'])
                    if key in before_set:
                        repeat_cases.append({
                            'session': session[:20],
                            'comp_ts': comp_ts,
                            'repeat_ts': e['ts'],
                            'agent': e['agent'],
                            'tool': e['tool'],
                            'args': e['args'][:60],
                        })
    except:
        pass

print(f'Found {len(repeat_cases)} potential compression-induced repeats')
for case in repeat_cases[:20]:
    print(f\"  {case['comp_ts']} → {case['repeat_ts']} | {case['agent']} | {case['tool']} | {case['args']}\")
